class Solution { fun combinationSum3(k:Int,n:Int):List<List<Int>>{val answer=mutableListOf<List<Int>>();val path=mutableListOf<Int>();fun dfs(start:Int,remaining:Int){if(path.size==k){if(remaining==0)answer.add(path.toList());return};for(value in start..9){if(value>remaining)break;path.add(value);dfs(value+1,remaining-value);path.removeAt(path.lastIndex)}};dfs(1,n);return answer} }
